INSERT INTO "RecruitmentTestQuestion" ("id", "testTypeId", "sortOrder", "prompt", "options", "correctIndex", "reverseScored", "active") VALUES
  ('rtq_log_01', 'rtt_logika_dasar', 1, 'Satu mesin produksi menghasilkan 150 unit per jam. Jika mesin beroperasi selama 7 jam dalam satu shift, berapa total unit yang dihasilkan dalam satu shift?', ARRAY['950', '1.000', '1.050', '1.100', '1.150'], 2, false, true),
  ('rtq_log_02', 'rtt_logika_dasar', 2, 'Dari 2.000 unit yang diproduksi hari ini, 40 unit dinyatakan reject (cacat). Berapa persen tingkat reject hari ini?', ARRAY['1%', '1,5%', '2%', '2,5%', '3%'], 2, false, true),
  ('rtq_log_03', 'rtt_logika_dasar', 3, 'Satu karung bahan baku beratnya 25 kg. Gudang menerima 48 karung. Berapa total berat bahan baku dalam ton?', ARRAY['1,0 ton', '1,1 ton', '1,2 ton', '1,3 ton', '1,4 ton'], 2, false, true),
  ('rtq_log_04', 'rtt_logika_dasar', 4, 'Target produksi adalah 480 unit dalam waktu 8 jam kerja. Berapa waktu maksimal yang boleh dipakai untuk menyelesaikan 1 unit, supaya target tercapai?', ARRAY['30 detik', '45 detik', '1 menit', '1,5 menit', '2 menit'], 2, false, true),
  ('rtq_log_05', 'rtt_logika_dasar', 5, 'Jam kerja normal adalah 8 jam per hari. Seorang operator bekerja selama 10,5 jam hari ini. Berapa jam lembur yang ia jalani?', ARRAY['1,5 jam', '2 jam', '2,5 jam', '3 jam', '3,5 jam'], 2, false, true),
  ('rtq_log_06', 'rtt_logika_dasar', 6, 'Gudang memiliki stok 960 unit komponen, akan dibagi rata ke 4 lini produksi. Berapa unit yang diterima tiap lini?', ARRAY['200', '220', '240', '260', '280'], 2, false, true),
  ('rtq_log_07', 'rtt_logika_dasar', 7, 'Standar sampling QC menetapkan 1 dari setiap 25 unit harus diperiksa. Jika hari ini diproduksi 1.500 unit, berapa unit yang harus diperiksa?', ARRAY['40', '50', '60', '70', '80'], 2, false, true),
  ('rtq_log_08', 'rtt_logika_dasar', 8, 'Target produksi harian adalah 1.800 unit. Hari ini hanya tercapai 1.530 unit. Berapa persen pencapaian target hari ini?', ARRAY['75%', '80%', '85%', '90%', '95%'], 2, false, true),
  ('rtq_log_09', 'rtt_logika_dasar', 9, 'Urutan proses produksi harus melewati Quality Check SEBELUM Pengemasan. Mana urutan yang benar?', ARRAY['Cek bahan baku - Pencampuran - Pencetakan - Pengemasan - QC', 'Cek bahan baku - Pencampuran - Pencetakan - QC - Pengemasan', 'Pencampuran - Cek bahan baku - Pencetakan - Pengemasan - QC', 'Cek bahan baku - Pencetakan - Pencampuran - Pengemasan - QC', 'QC - Cek bahan baku - Pencampuran - Pencetakan - Pengemasan'], 1, false, true),
  ('rtq_log_10', 'rtt_logika_dasar', 10, 'Sebuah pipa panjangnya 2,4 meter akan dipotong menjadi beberapa bagian, masing-masing 40 cm. Berapa bagian yang bisa dipotong?', ARRAY['4', '5', '6', '7', '8'], 2, false, true),
  ('rtq_log_11', 'rtt_logika_dasar', 11, 'Lanjutkan deret berikut: 3, 6, 12, 24, 48, ...?', ARRAY['72', '84', '96', '108', '120'], 2, false, true),
  ('rtq_log_12', 'rtt_logika_dasar', 12, 'Lanjutkan deret berikut: 2, 5, 10, 17, 26, ...?', ARRAY['33', '35', '37', '39', '41'], 2, false, true),
  ('rtq_log_13', 'rtt_logika_dasar', 13, 'Semua operator shift malam wajib memakai rompi reflektif. Dika memakai rompi reflektif. Apakah pasti benar bahwa Dika operator shift malam?', ARRAY['Pasti benar, karena rompi reflektif hanya dipakai shift malam', 'Belum tentu, bisa saja Dika memakai rompi itu karena alasan lain', 'Pasti salah, Dika bukan shift malam', 'Tidak berhubungan sama sekali', 'Ini membuktikan Dika seorang supervisor'], 1, false, true),
  ('rtq_log_14', 'rtt_logika_dasar', 14, 'Setiap mesin yang lolos uji kalibrasi diberi label hijau. Mesin nomor 7 tidak memiliki label hijau. Kesimpulan yang pasti benar?', ARRAY['Mesin nomor 7 belum pernah diuji kalibrasi', 'Mesin nomor 7 tidak lolos uji kalibrasi', 'Mesin nomor 7 rusak', 'Mesin nomor 7 akan diberi label hijau nanti', 'Tidak dapat disimpulkan apa-apa'], 1, false, true),
  ('rtq_log_15', 'rtt_logika_dasar', 15, 'Kunci Inggris - Mengencangkan Baut = Jangka Sorong - ...?', ARRAY['Memotong', 'Mengukur', 'Mengelas', 'Mengecat', 'Menimbang'], 1, false, true),
  ('rtq_log_16', 'rtt_logika_dasar', 16, 'Manakah yang BUKAN termasuk alat pelindung diri (APD)?', ARRAY['Helm keselamatan', 'Sarung tangan', 'Kacamata pelindung', 'Obeng', 'Sepatu safety'], 3, false, true),
  ('rtq_log_17', 'rtt_logika_dasar', 17, 'Lanjutkan pola huruf berikut: A, C, F, J, O, ...?', ARRAY['S', 'T', 'U', 'V', 'W'], 2, false, true),
  ('rtq_log_18', 'rtt_logika_dasar', 18, 'Jika lampu indikator merah menyala, mesin harus dihentikan. Jika mesin dihentikan, supervisor harus diberitahu. Lampu merah menyala. Apa yang pasti terjadi?', ARRAY['Mesin tetap berjalan', 'Supervisor tidak perlu diberitahu', 'Mesin dihentikan dan supervisor diberitahu', 'Lampu akan mati sendiri', 'Tidak ada yang bisa dipastikan'], 2, false, true),
  ('rtq_log_19', 'rtt_logika_dasar', 19, 'Pola rotasi shift: Pagi, Siang, Malam, berulang tiap 3 hari. Hari ke-1 adalah Pagi. Shift apa yang berlaku di hari ke-20?', ARRAY['Pagi', 'Siang', 'Malam', 'Libur', 'Tidak bisa ditentukan'], 1, false, true),
  ('rtq_log_20', 'rtt_logika_dasar', 20, 'Mesin A selalu di sebelah kiri mesin B. Mesin C selalu di sebelah kanan mesin B. Jika ketiganya berjajar, mesin mana yang di tengah?', ARRAY['Mesin A', 'Mesin B', 'Mesin C', 'Tidak bisa ditentukan', 'Semua benar'], 1, false, true);
